  { id: 1, name: '厨房美食广告 · AI 提示词', date: '2026-08-30 14:32', type: 'ai', prompt: 'Cinematic short-form commercial, 12 seconds. An Asian female creator in a refined studio kitchen presents a handcrafted seasonal dish.' },
  { id: 2, name: '春季新品短片 · 实拍拆解', date: '2026-08-29 18:06', type: 'real', prompt: '' },
  { id: 3, name: '品牌故事片 · 镜头复刻', date: '2026-08-27 09:48', type: 'real', prompt: '' }
])
const toggleHistory = () => { historyOpen.value = !historyOpen.value; if (historyOpen.value) window.setTimeout(ensureHistoryActions, 0) }
const openHistory = (item) => { historyOpen.value = false; videoType.value = item.type; if (item.prompt) promptText.value = item.prompt; router.push({ path: '/video/analyze', query: { history: String(item.id) } }) }
const handleHistoryClick = (event) => { if (event.target.closest('.history-item input')) return; const row = event.target.closest('.history-menu .history-item'); if (!row) return; const rows = [...document.querySelectorAll('.history-menu .history-item')]; const index = rows.indexOf(row); if (index >= 0) openHistory(reverseHistories.value[index]) }
const ensureHistoryActions = () => { document.querySelectorAll('.history-menu .history-item').forEach((row, index) => { if (row.querySelector('.history-open')) return; const button = document.createElement('button'); button.className = 'history-open'; button.type = 'button'; button.setAttribute('aria-label', '打开此条反推历史'); button.innerHTML = '<span class="material-symbols-outlined">arrow_forward</span>'; button.addEventListener('click', event => { event.stopPropagation(); openHistory(reverseHistories.value[index]) }); row.append(button) }) }
onMounted(() => document.addEventListener('click', handleHistoryClick))
onBeforeUnmount(() => document.removeEventListener('click', handleHistoryClick))

const promptText = ref(String(route.query.prompt || `Cinematic short-form commercial, 12 seconds. An Asian female creator in a refined studio kitchen presents a handcrafted seasonal dish. Start with an intimate macro push-in on the steam and texture, then orbit 180 degrees around the subject as she looks into camera with a confident half-smile. Finish with a smooth dolly-out revealing the warm dining scene. Premium editorial lighting, controlled shadows, tactile food details, natural micro-expressions, elegant camera choreography, shallow depth of field, subtle film grain.`))
const chartPoints = [62, 68, 73, 70, 82, 88, 84, 92, 89, 94, 90, 96, 93, 97, 95, 98]
const chartPath = computed(() => { const width = 720; const height = 80; const step = width / (chartPoints.length - 1); return chartPoints.map((value, index) => `${index ? 'L' : 'M'} ${index * step} ${height - (value - 50) * 1.5}`).join(' ') })
const areaPath = computed(() => `${chartPath.value} L 720 80 L 0 80 Z`)
const params = [
  { key: '主体人物', value: '亚洲女性美食创作者', tone: 'blue' },
  { key: '场景环境', value: '精致工作室厨房 · 暖色餐桌', tone: 'teal' },
  { key: '镜头运动', value: '微距推近 · 180°环绕 · 拉远', tone: 'teal' },
  { key: '光线氛围', value: '电影级暖光 · 柔和阴影', tone: 'purple' },
  { key: '画面风格', value: '高级商业广告 · 编辑感', tone: 'blue' },
  { key: '景深质感', value: '浅景深 · 35mm 胶片颗粒', tone: 'slate' },
  { key: '画幅时长', value: '16:9 · 12 秒', tone: 'slate' },
  { key: '负面提示词', value: '无字幕 · 无 Logo · 无抖动 · 无多余手指', tone: 'slate' },
  { key: '声音节奏', value: '环境音桥接 · 节奏型剪辑', tone: 'teal' }
