const cameraShots = [{ time: '00:00–00:03', action: '推镜头', note: 'Hook / 黄金三秒' }, { time: '00:03–00:05', action: '环绕 180°', note: '建立空间关系' }, { time: '00:05–00:09', action: '跟拍', note: '保持动作节奏' }, { time: '00:09–00:12', action: '拉远', note: '情绪释放 CTA' }]
const realMetrics = [{ label: '预计完播率', value: '78.4%', delta: '+12.6%', tone: 'up' }, { label: '情绪峰值数', value: '04', delta: '高于均值', tone: 'up' }, { label: '视觉留存指数', value: '8.7', delta: '/ 10', tone: 'neutral' }, { label: '节奏紧凑度', value: '91', delta: 'PCTL', tone: 'up' }]
const metricValues = ref(realMetrics.map(() => 0))
let metricTimer
const spotlightMove = (event) => { const el = event.currentTarget; const rect = el.getBoundingClientRect(); el.style.setProperty('--spot-x', `${event.clientX - rect.left}px`); el.style.setProperty('--spot-y', `${event.clientY - rect.top}px`) }
onMounted(() => { let frame = 0; metricTimer = window.setInterval(() => { frame += 1; metricValues.value = realMetrics.map(metric => { const target = parseFloat(metric.value); return Math.min(target, Number((target * Math.min(frame / 12, 1)).toFixed(1))) }); document.querySelectorAll('.premium-analyze .metric-card strong').forEach((node, index) => { const metric = realMetrics[index]; const value = metricValues.value[index]; node.textContent = metric.label === '预计完播率' ? `${value.toFixed(1)}%` : metric.label === '视觉留存指数' ? value.toFixed(1) : metric.label === '情绪峰值数' ? String(Math.round(value)).padStart(2, '0') : String(Math.round(value)) }); if (frame >= 12) window.clearInterval(metricTimer) }, 70); document.querySelector('.premium-analyze .premium-console')?.addEventListener('mousemove', spotlightMove) })
onBeforeUnmount(() => window.clearInterval(metricTimer))
const deepRows = [{ time: '00:00–00:03', scene: '蒸汽升腾的菜品特写，主体快速入画', camera: '推镜头', emotion: '好奇 · 紧张', score: 9.6 }, { time: '00:03–00:05', scene: '人物与餐桌空间建立关系', camera: '环绕 180°', emotion: '惊喜 · 信任', score: 8.9 }, { time: '00:05–00:09', scene: '手部动作与食材纹理连续切换', camera: '跟拍', emotion: '愉悦 · 沉浸', score: 8.4 }, { time: '00:09–00:12', scene: '拉远露出完整用餐场景，落到 CTA', camera: '拉远', emotion: '向往 · 行动', score: 8.1 }]
const keyframes = [{ time: '00:00', title: 'Macro hook', prompt: 'intimate macro push-in, steam texture' }, { time: '00:03', title: 'Orbit reveal', prompt: 'smooth 180 degree orbit, warm studio' }, { time: '00:07', title: 'Detail cut', prompt: 'tactile food detail, shallow DOF' }, { time: '00:10', title: 'Dolly out', prompt: 'wide dining scene, editorial finish' }]
const displayPrompt = ref('')

let typingTimer
const typePrompt = () => { window.clearInterval(typingTimer); displayPrompt.value = ''; let index = 0; typingTimer = window.setInterval(() => { displayPrompt.value = promptText.value.slice(0, index += 3); if (index >= promptText.value.length) window.clearInterval(typingTimer) }, 18) }
watch(promptText, typePrompt, { immediate: true })
const chineseLabels = new Map([
['VIDEO REVERSE ENGINEERING', '视频反推 · 智能分析'], ['Analysis Console', '创作逻辑分析台'], ['INPUT SOURCE', '输入方式'], ['ANALYSIS MODE', '分析模式'], ['WAITING FOR INPUT', '等待输入'], ['ANALYSIS WORKSPACE', '分析工作区'], ['AI DIMENSION RADAR', 'AI 维度雷达'], ['5 dimensions', '5 个维度'], ['KEYFRAMES', '关键帧'], ['4 moments', '4 个关键时刻'], ['PROMPT TERMINAL', '提示词终端'], ['typing synthesis complete', '提示词生成完成'], ['Copy prompt', '复制提示词'], ['EXTRACTED PARAMETERS', '提取参数'], ['8 factors', '8 项因素'], ['6 fields', '6 个字段'], ['CAMERA WORK / 运镜拆解', '运镜拆解'], ['4 key shots', '4 个关键镜头'], ['SUBTITLE SCRIPT / 字幕脚本', '字幕脚本'], ['EMOTION CURVE / 情绪曲线', '情绪曲线'], ['hover points for detail', '悬停查看详情'], ['Emotion & retention signal', '情绪与留存信号'], ['DEEP DIVE ANALYSIS / 深度解析表格', '深度解析表格'], ['4 scenes detected', '识别到 4 个场景'], ['TIME', '时间'], ['SCENE', '场景'], ['CAMERA WORK', '运镜技法'], ['EMOTION', '情绪'], ['PACING', '节奏'], ['PCTL', '百分位'], ['Macro hook', '微距开场'], ['Orbit reveal', '环绕展示'], ['Detail cut', '细节切换'], ['Dolly out', '拉远收束'], ['AI Parameter Confidence Score', 'AI 参数置信度'], ['12 parameters extracted', '已提取 12 个参数'], ['typing synthesis complete', '提示词合成完成'], ['4 moments', '4 个关键时刻']
])
let labelObserver
const reuseScriptText = '开场 0–3 秒：用蒸汽升腾的菜品微距特写制造好奇，配合一句反常识提问。3–5 秒：镜头环绕人物与餐桌，字幕落下核心卖点。5–9 秒：跟拍手部动作与食材细节，连续切换保持节奏。9–12 秒：拉远展示完整用餐场景，以“今晚，给自己一个好好吃饭的理由”收束并引导行动。'
const ensureReuseScript = () => { const real = document.querySelector('.real-console'); if (!real || real.querySelector('.reuse-script')) return; const block = document.createElement('section'); block.className = 'reuse-script'; block.innerHTML = '<div class="reuse-script-head"><span>总复用脚本</span><small>可直接交给编导 / AI 生成</small><button type="button">复制脚本</button></div><p></p><div class="reuse-script-foot"><span>复刻方法</span><b>Hook → 递进 → 细节 → CTA</b></div>'; block.querySelector('p').textContent = reuseScriptText; block.querySelector('button').addEventListener('click', async () => { try { await navigator.clipboard.writeText(reuseScriptText) } catch {} block.querySelector('button').textContent = '已复制'; setTimeout(() => { block.querySelector('button').textContent = '复制脚本' }, 1600) }); real.prepend(block) }
const applyChineseLabels = () => { const root = document.querySelector('.premium-analyze'); if (!root) return; const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); const nodes = []; let node; while ((node = walker.nextNode())) nodes.push(node); nodes.forEach(textNode => { let value = textNode.nodeValue; chineseLabels.forEach((cn, en) => { value = value.replaceAll(en, cn) }); if (value !== textNode.nodeValue) textNode.nodeValue = value }); const dimensionNames = { Lighting: '光影', Motion: '运镜', Subject: '主体', Setting: '场景', Color: '色彩', '光影质感': '光影', '镜头运动': '运镜', '主体表现': '主体', '场景构图': '场景', '风格色彩': '色彩' }; root.querySelectorAll('.radar-visual text').forEach(item => { if (dimensionNames[item.textContent]) item.textContent = dimensionNames[item.textContent] }); const parameterNames = { Lighting: '光线', Motion: '运镜', Subject: '主体', Ratio: '画幅', Duration: '时长', Grain: '颗粒' }; root.querySelectorAll('.parameter-row span').forEach(item => { if (parameterNames[item.textContent]) item.textContent = parameterNames[item.textContent] }) }
onMounted(() => { applyChineseLabels(); ensureReuseScript(); positionRadarLabels(); ensureHistoryActions(); labelObserver = new MutationObserver(() => { applyChineseLabels(); ensureReuseScript(); positionRadarLabels(); ensureHistoryActions() }); labelObserver.observe(document.querySelector('.premium-analyze'), { childList: true, subtree: true }) })
onBeforeUnmount(() => labelObserver?.disconnect())
onBeforeUnmount(() => window.clearInterval(typingTimer))
const updateParameterCount = () => { const count = document.querySelector('.premium-analyze .parameter-caption small'); if (count) count.textContent = '9 项因素' }
onMounted(updateParameterCount)
const positionRadarLabels = () => { const labels = document.querySelectorAll('.premium-analyze .radar-visual text'); const positions = [{ x: 90, y: 8, anchor: 'middle' }, { x: 176, y: 65, anchor: 'end' }, { x: 132, y: 147, anchor: 'middle' }, { x: 25, y: 147, anchor: 'middle' }, { x: 1, y: 65, anchor: 'start' }]; labels.forEach((label, index) => { const point = positions[index]; if (!point) return; label.setAttribute('x', point.x); label.setAttribute('y', point.y); label.setAttribute('text-anchor', point.anchor) }) }
onMounted(positionRadarLabels)
const startScan = () => { isScanning.value = true; analysisLoaded.value = false; setTimeout(() => { isScanning.value = false; hasVideo.value = true; analysisLoaded.value = true; typePrompt() }, 2200) }
const onFile = (event) => { if (event.target.files?.length) startScan() }
const onDrop = (event) => { if (event.dataTransfer?.files?.length) startScan() }
const parseUrl = () => { if (videoUrl.value.trim()) startScan() }
const copyPrompt = async () => { try { await navigator.clipboard.writeText(promptText.value) } catch { /* clipboard unavailable in local preview */ } copied.value = true; setTimeout(() => { copied.value = false }, 1800) }
const generateSame = () => { copyPrompt(); router.push({ path: '/video/workbench', query: { prompt: promptText.value } }) }
